# Calling rlm.finish to mark task completion
import os

files = {}
for f in sorted(os.listdir('crucible_hidden')):
    path = os.path.join('crucible_hidden', f)
    with open(path) as fh:
        content = fh.read()
    files[f] = {'tests': content.count('def test_'), 'size': len(content)}

print(f"Created {len(files)} test files in crucible_hidden/:")
for name, info in files.items():
    print(f"  {name}: {info['tests']} tests, {info['size']} bytes")
